    title = a[i].text();
    url = a[i].attr("href");
    size = 0.33;
    title = String(title).replace(/\s/g, "");
    url = baseUrl + String(url).replace(/\d+\/$/, "") + "{{page}}/";
    push(title, url, size);
  };

  push("🔥完本小说🔥", null, 1);
  for (var i = 0; i < b.length; i++) {
    title = b[i].text();
    url = b[i].attr("href");
    size = 0.33;
    title = String(title).replace(/\s/g, "");
    url = baseUrl + String(url).replace(/\d+\/$/, "")+"{{page}}/";
    push(title, url, size);
  };

  push("🔥排行榜单🔥", null, 1);
  for (var i = 0; i < c.length; i++) {
    title = c[i].text();
    url = c[i].attr("href");
    size = 0.33;
    title = String(title).replace(/\s/g, "");
    url = baseUrl + String(url).replace(/\d+\/$/, "");
    push(title, url, size);
  };

} else {
